const codes = ['cc-08','cc-09','cc-10','cc-11','cc-12','cc-13','cc-14'];
const han = s => (s.match(/[\u4e00-\u9fff]/g) || []).length;
let bad = 0;
for (const c of codes) {
  const r = await tools.read({ file_path: `vibe-coding-ppt/tutorials-content/${c}.json`, limit: 5000 });
  const text = r.lines.map(l => l.text).join('\n');
  let obj;
  try { obj = JSON.parse(text); } catch (e) { console.log(c + ' JSON 解析失败: ' + e.message); bad++; continue; }
  const lays = obj.slides.map(s => s.layout);
  const counts = lays.reduce((a,l)=>(a[l]=(a[l]||0)+1,a),{});
  const cover = obj.slides[0];
  const okKicker = cover.layout==='cover' && cover.kicker===`Vibe Coding 学习系列 · ${obj.code}`;
  console.log(`${c}.json | code=${obj.code} | category=${obj.category} | fileTitle=${obj.fileTitle} | deck=${obj.deck}`);
  console.log(`   slides=${obj.slides.length} | kickerOK=${okKicker} | ${JSON.stringify(counts)}`);
}
console.log('\nJSON 解析失败文件数: ' + bad);
", "description": "Read back and validate all 7 JSON files"}

